def unique_jobs(rows):
    seen = {}
    result = []
    for r in rows:
        src = r.get('source')
        src_id = r.get('source_id')
        key = (src, src_id if src_id is not None and src_id != '' else None)
        if key in seen:
            continue
        seen[key] = r
        result.append(r)
    return result
